import re

class SigmaTable:
    """只保存元数据（列名、公式、汇总），每次读取都现查仓库，不缓存任何数据。

    假设的入门类接口（题目提供，名字以实际 starter code 为准）：
      get_data_warehouse() -> DataWarehouse
      DataWarehouse.get_table(path) -> DataWarehouseTable，表不存在时抛 KeyError
      DataWarehouseTable.get_column(name) -> Column，列不存在时抛 KeyError
      Column.values -> list，缺失值为 None
    """
    TOKEN = re.compile(r'\s*(?:(\[[^\]]+\])|(\d+(?:\.\d+)?)|(.))')

    def __init__(self, name, table_path, get_data_warehouse):
        self.name = name
        self.table_path = table_path
        self.get_data_warehouse = get_data_warehouse
        self.formulas = {}          # 列名 -> 公式字符串
        self.summaries = []         # (函数名, 列名)

    # ---------- 元数据 ----------
    def add_column(self, name, formula):
        self.formulas[name] = formula

    def add_summary(self, func, column):
        if func not in self.AGG:
            raise ValueError(f"unknown summary {func}")
        if column not in self.formulas:
            raise ValueError(f"missing column {column}")
        self.summaries.append((func, column))

    # ---------- 读取 ----------
    def get_column(self, name):
        return self._eval_column(name, set())

    def get_summaries(self):
        return [(f"{f} of {c}", self.AGG[f](self.get_column(c))) for f, c in self.summaries]

    AGG = {'Min': min, 'Max': max, 'Sum': sum, 'Count': len,
           'Avg': lambda v: sum(v) / len(v) if v else 0}

    # ---------- 内部 ----------
    def _warehouse_column(self, table_path, col):
        try:
            values = self.get_data_warehouse().get_table(table_path).get_column(col).values
        except KeyError:
            raise ValueError(f"missing column {table_path}/{col}")
        return [0 if v is None else v for v in values]      # 缺失数据按 0 处理

    def _resolve(self, ref, visiting, current):
        if ref in self.formulas and ref != current:        # 本表的其他列（可能是计算列）
            return self._eval_column(ref, visiting)
        if '/' in ref:                                     # 完整路径 [表路径/列名]
            path, col = ref.rsplit('/', 1)
            return self._warehouse_column(path, col)
        return self._warehouse_column(self.table_path, ref)   # 含 [Col A] 引用自己：即仓库里的同名列

    def _eval_column(self, name, visiting):
        if name not in self.formulas:
            raise ValueError(f"missing column {name}")
        if name in visiting:
            raise ValueError(f"circular reference at {name}")
        visiting = visiting | {name}
        tokens = [m.group(1) or m.group(2) or m.group(3)
                  for m in self.TOKEN.finditer(self.formulas[name]) if m.group(0).strip()]
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def take():
            nonlocal pos
            pos += 1
            return tokens[pos - 1]

        def combine(a, b, op):
            n = max(len(a), len(b))
            a = a + [0] * (n - len(a))                     # 列长度不同：缺的行按 0
            b = b + [0] * (n - len(b))
            return [op(x, y) for x, y in zip(a, b)]

        def atom():
            tok = take()
            if tok == '(':
                v = expr()
                if take() != ')':
                    raise ValueError("expected )")
                return v
            if tok == '-':
                return [-x for x in atom()]
            if tok.startswith('['):
                return self._resolve(tok[1:-1], visiting, name)
            return [float(tok) if '.' in tok else int(tok)]   # 常数，下面会广播

        def broadcast(a, b):
            if len(a) == 1 and len(b) != 1:
                a = a * len(b)
            if len(b) == 1 and len(a) != 1:
                b = b * len(a)
            return a, b

        def term():
            v = atom()
            while peek() in ('*', '/'):
                op = take()
                a, b = broadcast(v, atom())
                v = combine(a, b, (lambda x, y: x * y) if op == '*' else (lambda x, y: x / y if y else 0))
            return v

        def expr():
            v = term()
            while peek() in ('+', '-'):
                op = take()
                a, b = broadcast(v, term())
                v = combine(a, b, (lambda x, y: x + y) if op == '+' else (lambda x, y: x - y))
            return v

        result = expr()
        if pos != len(tokens):
            raise ValueError(f"bad formula for {name}")
        return result
